    /* empty */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.check
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.check = function (div) {
    /* sdd-asis-lifecycle:begin fn_check — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (div === '1') {
        if ($c.util.getComponent("cominfo")) {
            if ($c.util.getComponent("cominfo").getStyle("display") === 'block') {
                $c.util.getComponent("cominfo").setStyle("display", 'none');
            } else {
                $c.util.getComponent("cominfo").setStyle("display", 'block');
            }
        }
    } else {
        if (div === '2') {
            if (document.all('attach')) {
                if (document.all('attach').style.display === 'block') {
                    document.all('attach').style.display = 'none';
                } else {
                    document.all('attach').style.display = 'block';
                }
            }
        } else {
            if (div === '3') {
                if ($c.util.getComponent("caut")) {
                    if ($c.util.getComponent("caut").getStyle("display") === 'block') {
                        $c.util.getComponent("caut").setStyle("display", 'none');
                    } else {
                        $c.util.getComponent("caut").setStyle("display", 'block');
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excel = async function () {
    /* sdd-asis-lifecycle:begin fn_excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let documentHtml = '';
    if ($c.util.getComponent("cominfo")) {
        if ($c.util.getComponent("cominfo").getStyle("display") === 'block') {
            $c.util.getComponent("cominfo_img").innerHTML = '';
            documentHtml = documentHtml + $c.util.getComponent("cominfo").innerHTML;
            $c.util.getComponent("cominfo_img").innerHTML = '<img  src="/img/submission/main/print_1.gif">';
        }
    }
    if ($c.util.getComponent("maindoc")) {
        if ($c.util.getComponent("maindoc").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("maindoc").innerHTML;
        }
    }
    if (document.all('attach')) {
        if (document.all("attach").style.display === 'block') {
            documentHtml = documentHtml + document.all("attach").innerHTML;
        }
    }
    if ($c.util.getComponent("caut")) {
        if ($c.util.getComponent("caut").getStyle("display") === 'block') {
            $c.util.getComponent("caut_img").innerHTML = '';
            documentHtml = documentHtml + $c.util.getComponent("caut").innerHTML;
            $c.util.getComponent("caut_img").innerHTML = '<img src="/img/submission/main/print_2.gif">';
        }
    }
    $c.util.getComponent('dma_excelReq').set('documentHtml', documentHtml);
    (document.submitFrm || { elements: [] }).action = 'disclosure.do?method=searchDocumentPrintExcel';
    await scwin.tx_fn_excel();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goPrint
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goPrint = async function () {
    /* sdd-asis-lifecycle:begin fn_goPrint — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const langSelect = $c.util.getComponent('slc_checkLang').getValue();
